window.products.push({"id":347946,"name":"Sleep Revolution MyGel 12 inch Memory Foam Mattress, King","category":"homeandappliances","retail price":1099.03,"sale price":null,"image":"https://m.media-amazon.com/images/I/811vic+OYKL._AC_SL1500_.jpg","description":"Enjoy the cooling comfort and memory foam pressure relief support of a Night Therapy MyGel Memory Foam mattress. MyGel Memory Foam is an open cell memory foam offering improved airflow movement while providing a customized level of support featuring our Pressure Relief system. Rest easy with the cooling comfort and memory foam pressure relief support from Night Therapy. Night Therapy Memory Foam is made with Green Tea, ActivFRESH Charcoal, and Natural Plant Oil to naturally keep your mattress fresh. Please open your mattress within 72 hours of receipt and allow 48 hours for your new mattress to return to its original, plush shape.","images":["https://m.media-amazon.com/images/I/811vic+OYKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Zinus","source_asin":"B07BN7HFGD","category_path":"Home & Kitchen"},"sku":"BM-347946","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07BN7HFGD","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07BN7HFGD","price_pending":true,"merchant_ready":false});
